[421] = { en = "Prove Your Worth", tier = 1,
  t = "Bewijs wat je waard bent",
  d = "Lady Sylvanas heeft Varimathras opgedragen om de landen van de mensen en de dwergen in het zuiden te veroveren.$b$bMaar dan is er die dwaas, Arugal. Hij is een bedrieger uit Dalaran, en nu een vervloekt beest van Shadowfang Keep. Hij liet zijn roekeloze magie grote schade aanrichten in Silverpine Forest. Dat is een belangrijk strategisch bolwerk.$b$bIk heb iemand nodig die goed kan vechten. Die persoon moet helpen om de rommel van Arugal op te ruimen. Bewijs jezelf aan mij: dood 5 Moonrage Whitescalps. Je vindt die ellendige beesten vaak vlak naast de weg, onderaan de heuvel.",
  o = "Dalar Dawnweaver in de Sepulcher wil dat je 5 Moonrage Whitescalps doodt.",
  p = "Als je jezelf aan mij wilt bewijzen, moet je 5 Moonrage Whitescalps doden. Doe je dat, dan zorg ik ervoor dat je vaardigheden voor waardigere opdrachten worden gebruikt.",
  c = "Je hebt me goed gediend, $c. Het is duidelijk dat je een waardige helper voor me zult zijn. Ik bereid me voor om Silverpine Forest te bevrijden van de vloek van Arugal.",
