[6321] = { en = "Supplying the Sepulcher", tier = 1,
  t = "Voorraden voor de Sepulcher",
  d = "Executor Hadrec vroeg me om onze uitrusting in de Sepulcher te tellen. De Scourge, en erger, loert in de bossen. Daarom wil hij niet dat de Deathguards uitrusting missen die ze misschien nodig hebben.$B$BIk zag dat we over het algemeen genoeg voorraad hebben. Maar we hebben wel meer wapens nodig. Die moeten de wapens vervangen die in het veld verloren zijn.$B$BHier is een bestelling met wat we nodig hebben, voor de wapenhandelaar Gordon Wendham in de Undercity. Breng de bestelling naar onze vleermuismeester, Karos Razok, en praat met hem over vervoer naar de Undercity.",
  o = "Breng Podrig's Order naar Karos Razok.",
  p = "Je lijkt hier voor officiële zaken te zijn...",
  c = "Ah, een bestelling voor voorraden. Je wilt hiermee vast naar de Undercity. En snel, want de Sepulcher mag niet te weinig voorraad hebben.",
  g = { {"voorraden", "supplies (voorraad)"}, {"uitrusting", "equipment, gear"}, {"loert", "lurks (loeren)"}, {"over het algemeen", "in general"}, {"vervangen", "to replace"}, {"bestelling", "order"}, {"wapenhandelaar", "weapon dealer"}, {"vleermuismeester", "bat master"}, {"vervoer", "transport"}, {"officiële zaken", "official business"} },
},

[6322] = { en = "Michael Garrett", tier = 1,
  t = "Michael Garrett",
  d = "Ik heb de voorraden voor de Sepulcher in deze krat gedaan. Ben je al in de Sepulcher geweest en heb je met hun vleermuismeester gepraat? Dan mag je op een vleermuis terug naar hem vliegen.$B$BPraat met de vleermuismeester van de Undercity, Michael Garrett. Hij kan je een vleermuis naar de Sepulcher geven.",
  o = "Breng Gordon's Crate naar Michael Garrett.",
  p = "Als je ver moet reizen, dan is een vleermuis de beste keuze.",
  c = "Deze krat moet naar de Sepulcher in Silverpine? Dat is makkelijk. Onze vleermuizen vliegen er elke dag heen.",
  g = { {"voorraden", "supplies (voorraad)"}, {"krat", "crate"}, {"vleermuismeester", "bat master"}, {"vleermuis", "bat"}, {"keuze", "choice, option"}, {"vleermuizen", "bats (vleermuis)"} },
},

[6323] = { en = "Ride to the Undercity", tier = 1,
  t = "Een rit naar de Undercity",
  d = "Een van mijn vleermuizen kan je naar de Undercity brengen, voor een klein bedrag. Praat nog eens met me als je klaar bent. Dan regelen we je vervoer.$B$BJe vindt Gordon Wendham in de Trade Quarter van de Undercity. Mijn vleermuis landt in diezelfde wijk.",
  o = "Koop een vleermuisrit naar de Undercity bij de vleermuismeester Karos Razok. Breng daarna Podrig's Order naar Gordon Wendham in de Undercity.",
  p = "Ik houd mijn wapens in topconditie. Ze zijn schoon en klaar voor gebruik.",
  c = "Een bestelling van de Sepulcher? Goed dan. Het is een eer om hen te dienen die onze Dark Lady dienen.",
  g = { {"rit", "ride"}, {"bedrag", "amount, fee"}, {"regelen", "to arrange"}, {"vervoer", "transport"}, {"wijk", "quarter, district"}, {"vleermuisrit", "bat ride"}, {"topconditie", "top condition"}, {"eer", "honor"} },
},

[6324] = { en = "Return to Podrig", tier = 1,
  t = "Terug naar Podrig",
  d = "De vleermuismeester in de Sepulcher is Karos Razok. Heb je hem al ontmoet? Dan kan ik je een vleermuis geven om terug naar hem te vliegen.$B$BOnze vleermuizen vliegen altijd naar de Undercity. Maar voor verre plaatsen moet de rijder eerst zelf naar dat gebied gaan en met de vleermuismeester daar praten.$B$BJe hebt Karos in de Sepulcher ontmoet, dus je mag nu met vleermuizen daarheen vliegen. Praat nog eens met me als je klaar bent.",
  o = "Koop een vleermuisrit naar de Sepulcher bij de vleermuismeester Michael Garrett. Breng daarna Gordon's Crate naar Deathguard Podrig in de Sepulcher.",
  p = "$N, je bent terug. Heb je onze voorraden uit de Undercity?",
  c = "Goed gedaan, $N. Met deze wapens worden onze Deathguards niet onvoorbereid verrast.$B$BJe hebt onze Dark Lady een waardevolle dienst bewezen.",
  g = { {"verre", "remote, distant (ver)"}, {"rijder", "rider"}, {"gebied", "area"}, {"daarheen", "there (to that place)"}, {"onvoorbereid", "unprepared"}, {"verrast", "caught by surprise (verrassen)"}, {"waardevolle", "valuable (waardevol)"}, {"een dienst bewezen", "done a service (een dienst bewijzen)"} },
},

[422] = { en = "Arugal's Folly", tier = 1,
  t = "De dwaasheid van Arugal",
  d = "Ik begrijp niet hoe Arugal ooit in de Kirin Tor werd toegelaten. Zijn kennis van spreuken leek zo doorzichtig als een bolletje van geblazen glas.$b$bWat nu belangrijk is: ik moet precies weten welke magie Arugal gebruikte. Dan kan ik die tegen hem gebruiken en Silverpine Forest voor de Dark Lady veiligstellen.$b$bArugal verbleef eerst op de tarweboerderij net ten noorden van de brug. Een van de Deathstalkers zag daar wat spreukenboeken, maar kon ze niet meenemen. Haal voor mij de spreuk met de naam Remedy of Arugal uit die boeken.",
  o = "Haal de Remedy of Arugal voor Dalar Dawnweaver in de Sepulcher.",
  p = "Ik moet eerst de spreuk Remedy of Arugal bestuderen, $c. Pas dan weet ik waar we hier mee te maken hebben. Breng hem nu naar me, of ik moet een waardige dienaar voor mezelf zoeken.",
  c = "Dit is precies de spreuk die ik zocht, $c. Als je toewijding aan de zaak van de Dark Lady nooit faalt, dan zul je zien dat je een mooie toekomst hebt bij de Forsaken.",
  g = { {"dwaasheid", "folly, foolishness"}, {"toegelaten", "accepted, admitted (toelaten)"}, {"doorzichtig", "transparent"}, {"geblazen", "blown (blazen)"}, {"veiligstellen", "to secure"}, {"verbleef", "stayed (verblijven)"}, {"tarweboerderij", "wheat farm"}, {"spreukenboeken", "spellbooks (spreukenboek)"}, {"waar we mee te maken hebben", "what we are dealing with"}, {"toewijding", "dedication"}, {"faalt", "fails (falen)"} },
},

[429] = { en = "Wild Hearts", tier = 1,
  t = "Wilde harten",
  d = "Mijn broer Quinn is zwaar gewond door de ghoul Ivar the Foul. Ik weet niet of hij goed zal genezen zonder hulp van magie. Ik ben geen apotheker, maar ik weet wel dat onze apothekers geneesdrankjes kunnen maken van de verkleurde harten van worgs.$B$BVerzamel zulke harten en breng ze naar Apothecary Renferrel in de Sepulcher, in het zuiden. Kom daarna met het drankje hier terug.$B$BJe vindt veel worgs tussen hier en Malden's Orchard in het oosten.",
  o = "Verzamel 6 discolored worg hearts en breng ze naar Apothecary Renferrel in de Sepulcher.",
  p = "Mijn tijd is kort, $c, want de Dark Lady heeft me een zware taak gegeven.",
  c = "<Renferrel neemt de harten aan.>$B$BHet is zorgwekkend om te horen dat onze Deathstalkers hun missie niet hebben volbracht.$B$BLaten we hopen dat zulke mislukkingen zeldzaam zijn.$B$BIk geef je zo het drankje. Maar hier is het recept. Als die Deathstalkers later weer hulp nodig hebben, kun je het misschien zelf geven.",
  g = { {"gewond", "hurt, wounded"}, {"genezen", "to heal"}, {"apotheker", "apothecary"}, {"geneesdrankjes", "healing potions (geneesdrankje)"}, {"verkleurde", "discolored (verkleurd)"}, {"drankje", "potion"}, {"zware taak", "grave task"}, {"zorgwekkend", "troubling, worrying"}, {"volbracht", "accomplished (volbrengen)"}, {"mislukkingen", "failures (mislukking)"}, {"zeldzaam", "rare"} },
},

