[449] = { en = "The Deathstalkers' Report", tier = 1,
  t = "Het rapport van de Deathstalkers",
  d = "De wonden van Quinn genezen, maar ik wil ons rapport zo snel mogelijk naar High Executor Hadrec brengen. Er staat informatie in die heel belangrijk is voor de bezetting van Silverpine door de Forsaken.",
  o = "Breng het Deathstalker Report naar High Executor Hadrec in de Sepulcher.",
  p = "Heb je ontdekt wat er met de Deathstalkers is gebeurd?",
  c = "Ik had niet gerekend op zoveel Scourge in Silverpine Forest. En ook niet op de problemen die onze Deathstalkers hadden bij hun verkenning.$B$BJe hulp aan onze Deathstalkers was heel waardevol, $N. En je zult daarvoor geprezen worden.",
