[425] = { en = "Ivar the Foul", tier = 1,
  t = "Ivar the Foul",
  d = "Mijn broer Quinn en ik moesten Silverpine Forest verkennen en verslag uitbrengen aan High Executor Hadrec. Maar we kwamen niet ver. Toen we door deze boerderij liepen, werden we aangevallen door de ghoul Ivar the Foul.$B$BWe zijn ontsnapt aan Ivar, maar hij heeft Quinn zwaar toegetakeld. Quinn geneest door het drankje dat je hem gaf. Maar Ivar komt misschien terug voordat Quinn hersteld is.$B$BDood Ivar, zodat Quinn tijd heeft om te genezen. Ivar is meestal in de schuur daarginds. Hij wacht tot ik niet meer oplet.",
  o = "Dood Ivar the Foul en breng Ivar's Head naar Rane Yorick bij de Ivar Patch.",
  p = "Heb je Ivar the Foul gedood? Als je het niet voor mij en mijn broer doet, doe het dan voor de Forsaken.",
  c = "Ah, dank je. Ik ben je dankbaar, $N.$B$BEn ik zal je noemen in het rapport voor mijn meerderen.",
  g = { {"verkennen", "to scout, to recon"}, {"verslag uitbrengen", "to report"}, {"aangevallen", "attacked (aanvallen)"}, {"ontsnapt", "escaped (ontsnappen)"}, {"toegetakeld", "mauled, badly hurt (toetakelen)"}, {"hersteld", "recovered (herstellen)"}, {"schuur", "barn"}, {"daarginds", "over there, yonder"}, {"oplet", "pays attention (opletten)"}, {"dankbaar", "grateful"}, {"meerderen", "superiors (meerdere)"} },
