[428] = { en = "Lost Deathstalkers", tier = 1,
  t = "Vermiste Deathstalkers",
  d = "Een paar weken geleden zijn twee van onze Deathstalkers, Rane en Quinn Yorick, op verkenningsmissie gestuurd door het noorden van Silverpine. We hebben niets meer van ze gehoord.$B$BMisschien zijn ze slachtoffer geworden van de Scourge. Maar als dat waar is, wil ik dat het bevestigd wordt. Zoek deze Deathstalkers.$B$BHun eerste doel was om de boerderijen in het noorden van Silverpine te verkennen. Begin daar met zoeken.",
  o = "Zoek de Deathstalkers Quinn en Rane Yorick.",
  c = "Je hebt ons gevonden! En geen moment te vroeg...",
  g = { {"vermiste", "lost, missing (vermist)"}, {"verkenningsmissie", "reconnaissance mission"}, {"slachtoffer", "victim"}, {"bevestigd", "confirmed (bevestigen)"}, {"doel", "objective, goal"}, {"verkennen", "to scout"}, {"geen moment te vroeg", "not a moment too soon"} },
