[447] = { en = "A Recipe For Death", tier = 1,
  t = "Een recept voor de dood",
  d = "Arthas heeft veel te veel troepen. Maar met een New Plague kunnen we zowel het leger van de Scourge als de menselijke plaag voorgoed uitroeien.$b$bMijn onderzoek heeft bewezen dat spinnenbloed samen met een gif uit het hart van een grijze beer een dodelijk drankje oplevert. Verzamel monsters van de spinnen in de Skittering Dark in het noordwesten, en van de beren die door heel Silverpine Forest zwerven. Breng de ingrediënten naar Master Apothecary Faranell van de Royal Apothecary Society in de Undercity.",
  o = "Verzamel 6 Grizzled Bear Hearts en 6 monsters Skittering Blood en breng ze naar Master Apothecary Faranell in de Undercity.",
  p = "Gegroet, $c. Wat heb je te zoeken bij de Royal Apothecary Society?",
  c = "Wat goed van Apothecary Renferrel om je naar mij te sturen, $N. Deze monsters zullen de zaak zeker helpen. Ik ga meteen hun giftige en besmettelijke eigenschappen bestuderen.",
  g = { {"troepen", "troops, forces (troep)"}, {"leger", "army"}, {"plaag", "plague, infestation"}, {"voorgoed", "for good, once and for all"}, {"uitroeien", "to eradicate"}, {"gif", "poison, toxin"}, {"oplevert", "results in (opleveren)"}, {"monsters", "samples (monster)"}, {"zwerven", "wander (zwerven)"}, {"Gegroet", "Hail, greetings"}, {"giftige", "toxic (giftig)"}, {"besmettelijke", "contagious (besmettelijk)"}, {"eigenschappen", "properties (eigenschap)"} },
},

[3221] = { en = "Speak with Renferrel", tier = 1,
  t = "Praat met Renferrel",
  d = "Terwijl je onze Deathstalkers hielp, heeft Apothecary Renferrel je laten oproepen. Hij gaf me geen details. Maar hij wilde met je praten over de wolvenharten die je hem had gegeven.",
  o = "Praat met Apothecary Renferrel in de Sepulcher.",
  c = "Ah, heel goed. Er is iets met de wolvenharten die je me eerder bracht. Daar moeten we aandacht aan besteden.",
  g = { {"terwijl", "while"}, {"oproepen", "to summon"}, {"wolvenharten", "wolf hearts (wolvenhart)"}, {"eerder", "earlier"}, {"aandacht besteden", "to pay attention"} },
