[423] = { en = "Arugal's Folly", tier = 1,
  t = "De dwaasheid van Arugal",
  d = "Ik heb het werk van Arugal onderzocht, en mijn ergste vermoedens zijn bevestigd. Die oude prutser was niet eens goed genoeg om in Dalaran de po's schoon te maken. Laat staan om de Kirin Tor te vertegenwoordigen in hun moeilijkste uur. Dwazen!$b$bArugal gebruikte betoverde voorwerpen om zijn zwakke magie sterker te maken. Ik moet die voorwerpen zelf bekijken. Ga op pad en dood Moonrage Gluttons en Moonrage Darksouls, tot je genoeg van hun betoverde boeien hebt voor mijn onderzoek. Die smerige wezens zijn in het noorden en oosten gezien.",
  o = "Breng 6 Glutton Shackles en 3 Darksoul Shackles naar Dalar Dawnweaver in de Sepulcher.",
  p = "Ik heb 6 Glutton Shackles en 3 Darksoul Shackles nodig. Pas dan kan ik de situatie beoordelen en een definitieve oplossing voor Arugal bedenken. Doe nu wat ik vraag en dood Moonrage Gluttons en Moonrage Darksouls, tot je hebt wat ik nodig heb.",
  c = "Ik hoop dat ik genoeg energie uit zo'n klein aantal kan halen. Misschien had ik je meer boeien moeten laten halen.$b$bToch heb je veel vaardigheid laten zien bij het verzamelen hiervan, $C.",
  g = { {"vermoedens", "suspicions (vermoeden)"}, {"prutser", "hack, bungler"}, {"po's", "chamber pots (po)"}, {"laat staan", "let alone"}, {"vertegenwoordigen", "to represent"}, {"betoverde", "enchanted (betoverd)"}, {"voorwerpen", "items, objects (voorwerp)"}, {"boeien", "shackles (boei)"}, {"smerige", "foul, filthy (smerig)"}, {"beoordelen", "to assess"}, {"definitieve oplossing", "final solution"}, {"vaardigheid", "skill"} },
},

[437] = { en = "The Dead Fields", tier = 1,
  t = "De Dead Fields",
  d = "Onze eerste verkenningsrapporten van Silverpine laten zien dat de rot hides een basis hebben op een oude boerderij in het noorden: de Dead Fields. We hebben kleine aanvallen op ze gedaan. Maar elke keer krijgen ze hulp van de banshee Nightlash. Zij gebruikt haar magie om onze troepen te verjagen.$B$BWe willen dat Nightlash vernietigd wordt.$B$BGa naar de Dead Fields en val de rot hides aan. Zie je Nightlash niet? Dood dan rot hides tot ze verschijnt, en versla haar daarna.$B$BHaar essentie verandert in stof. Breng me dat stof als bewijs.",
  o = "Dood rot hide gnolls bij de Dead Fields.$B$BAls Nightlash verschijnt, dood haar dan.$B$BBreng de Essence of Nightlash naar High Executor Hadrec in de Sepulcher.",
  p = "Heb je Nightlash verslagen, $N? Ons succes tegen de rot hides hangt af van haar vernietiging!",
  c = "Ik hoorde over je geslaagde aanval op de rot hides, $N, en deze essentie bewijst dat Nightlash dood is.$B$BDe Scourge heeft vandaag terrein verloren. Je waarde voor de Forsaken groeit.",
  e = "Ga de Dead Fields binnen",
  g = { {"verkenningsrapporten", "scouting reports (verkenningsrapport)"}, {"aanvallen", "assaults, attacks (aanval)"}, {"banshee", "banshee: a wailing female spirit"}, {"verjagen", "to drive away, to rout"}, {"vernietigd", "destroyed (vernietigen)"}, {"verschijnt", "appears (verschijnen)"}, {"versla", "defeat (verslaan)"}, {"essentie", "essence"}, {"stof", "dust"}, {"vernietiging", "destruction"}, {"geslaagde", "successful (geslaagd)"}, {"terrein verloren", "lost ground (terrein verliezen)"} },
},

[477] = { en = "Border Crossings", tier = 1,
  t = "Over de grens",
  d = "Zoals je misschien weet, blijft het stadje Ambermill een bron van menselijk verzet. Dat komt vooral door de steun van de tovenaars van Dalaran.$b$bIk weet niet wat hun plan is. Maar ze tonen interesse in een afgelegen dorpje als Ambermill, dus het moet belangrijker zijn dan het lijkt.$b$bZe sturen kratten per wagen uit Hillsbrad. Veel van die voorraden komen terecht in een klein kamp ten noorden van Pyrewood Village. Haal de inhoud van een krat en breng die naar mij.",
  o = "Haal de inhoud van een van de kratten van de tovenaars van Dalaran. Je vindt Pyrewood Village in het zuiden.",
  c = "<Je wrikt het deksel van de krat open en vindt allerlei voorwerpen die zorgvuldig zijn ingepakt. Bovenop ligt een bundel kaarten, geel van ouderdom. Ze lijken Silverpine Forest en andere delen van het westen van Lordaeron te tonen.$b$bOnder de kaarten ligt een geheimzinnige magische hanger.>",
  g = { {"grens", "border"}, {"bron", "source"}, {"verzet", "opposition, resistance"}, {"steun", "support"}, {"tovenaars", "wizards (tovenaar)"}, {"afgelegen", "remote, backwater"}, {"komen terecht", "end up (terechtkomen)"}, {"inhoud", "contents"}, {"wrikt open", "pry open (openwrikken)"}, {"deksel", "lid"}, {"zorgvuldig", "carefully"}, {"ouderdom", "age, old age"}, {"geheimzinnige", "mysterious (geheimzinnig)"}, {"hanger", "pendant"} },
},

[481] = { en = "Dalar's Analysis", tier = 1,
  t = "De analyse van Dalar",
  d = "Breng de hanger naar Dalar Dawnweaver. Misschien kan hij meer licht werpen op de plannen van de tovenaars.",
  o = "Breng de hanger met runen naar Dalar Dawnweaver in de Sepulcher.",
  p = "Ja, $C? Wat is er?",
  c = "Interessant, nog meer sluwe plannen van de Kirin Tor, zo lijkt het. Dit is een krachtig artefact. Machtige tovenaars van de Kirin Tor gebruikten het vaak om magische energie te kanaliseren.$b$bZe brengen er zoveel naar Ambermill. Dat betekent dat ze met een groot project bezig moeten zijn.$b$bIk ga kijken of ik door hun schilden heen kan breken en kan ontdekken wat ze van plan zijn.",
  g = { {"hanger", "pendant"}, {"licht werpen op", "to shed light on"}, {"runen", "runes (rune)"}, {"sluwe", "cunning (sluw)"}, {"artefact", "artifact"}, {"kanaliseren", "to channel"}, {"schilden", "shields (schild)"}, {"van plan", "intending, planning"} },
},

[482] = { en = "Dalaran's Intentions", tier = 1,
  t = "De bedoelingen van Dalaran",
  d = "Natuurlijk! Hoe kon ik dat vergeten?$b$bAmbermill was een van de plekken die de Kirin Tor had uitgekozen. Dat kwam doordat er een slapend knooppunt van ley-energie ligt. De tovenaars zijn vast van plan om het knooppunt weer te activeren en de energie te gebruiken voor een groter doel.$b$bDat mogen we niet laten gebeuren...$b$bEr is veel kracht nodig om de ley-energie in het gebied te activeren. We kunnen ze vertragen door de hangers van de tovenaars af te pakken.$b$bGeef deze informatie door aan Allister. Hij beslist wat we gaan doen.",
  o = "Praat met Shadow Priest Allister in de Sepulcher.",
  c = "Je brengt slecht nieuws, $N. Als Dalar gelijk heeft, en ik heb geen reden om te denken van niet, dan moeten we snel handelen.$b$bIk moet met hem overleggen over ons aanvalsplan. Maar intussen moeten we hun voortgang vertragen.",
  g = { {"bedoelingen", "intentions (bedoeling)"}, {"uitgekozen", "chosen, earmarked (uitkiezen)"}, {"slapend", "dormant, sleeping"}, {"knooppunt", "node"}, {"activeren", "to activate"}, {"vertragen", "to delay, to stall"}, {"af te pakken", "to take away (afpakken)"}, {"geef door", "pass on, relay (doorgeven)"}, {"handelen", "to act"}, {"overleggen", "to confer"}, {"aanvalsplan", "plan of attack"}, {"voortgang", "progress"} },
},

[99] = { en = "Arugal's Folly", tier = 1,
  t = "De dwaasheid van Arugal",
  d = "Hoe beter ik de magie van Arugal begrijp, hoe meer ik die stumper veracht. Mijn onderzoek naar zijn zogenaamde remedie is bijna klaar.$b$bMijn kennis is compleet als ik weet welke betovering het vreemde gedrag in Pyrewood Village veroorzaakt. Overdag lijken de boeren mensen. Maar als de zon ondergaat, veranderen de dorpelingen in Moonrage Worgen.$b$bIk moet energie halen uit de betoverde boeien die Arugal op hen heeft gelegd. Breng me zes betoverde Pyrewood Shackles, $N.",
  o = "Breng 6 Pyrewood Shackles naar Dalar Dawnweaver in de Sepulcher.",
  p = "Heb je de Pyrewood Shackles al, $N?",
  c = "Je doorzettingsvermogen verdient lof. Met de kennis die je me hielp verzamelen, zal Arugal vallen en wordt zijn roekeloze magie ongedaan gemaakt. Proost op jou, $N.",
  g = { {"stumper", "hapless fool"}, {"veracht", "despise (verachten)"}, {"zogenaamde", "so-called (zogenaamd)"}, {"remedie", "remedy"}, {"betovering", "enchantment"}, {"gedrag", "behavior"}, {"overdag", "by day"}, {"dorpelingen", "villagers, townsfolk (dorpeling)"}, {"boeien", "shackles (boei)"}, {"doorzettingsvermogen", "persistence"}, {"verdient lof", "is commendable (lof verdienen)"}, {"ongedaan gemaakt", "undone (ongedaan maken)"}, {"Proost", "Cheers"} },
},

[424] = { en = "Arugal's Folly", tier = 1,
  t = "De dwaasheid van Arugal",
  d = "Het gaat inderdaad langer duren dan ik dacht om de duistere geheimen achter de betoveringen van Arugal te ontdekken.$b$bMaar intussen moet jij een klein probleem oplossen dat onze Deathstalkers hebben ontdekt. Het lijkt erop dat Arugal zijn magie heeft laten verspreiden naar de Deep Elem Mine, in de heuvels in het zuidoosten.$b$bDe mijn zou heel nuttig zijn voor de opmars van Varimathras.$b$bIk wil dat je de besmette voorman van de mijn onthoofdt: Grimson the Pale. Met zijn dood wordt de mijn van ons.",
  o = "Dood Grimson the Pale en breng zijn hoofd naar Dalar Dawnweaver in de Sepulcher.",
  p = "Is Grimson the Pale gedood? Varimathras zal niet blij zijn als we zijn bevel negeren.",
  c = "Uitstekend. De mijn zal onze troepen prachtige grondstoffen geven terwijl we ons over Silverpine en Azeroth verspreiden.",
  g = { {"inderdaad", "indeed"}, {"duistere", "dark (duister)"}, {"betoveringen", "enchantments (betovering)"}, {"intussen", "in the meantime"}, {"verspreiden", "to spread"}, {"opmars", "advance"}, {"besmette", "tainted, infected (besmet)"}, {"voorman", "foreman"}, {"onthoofdt", "behead (onthoofden)"}, {"bevel", "order, bidding"}, {"negeren", "to ignore"}, {"grondstoffen", "resources (grondstof)"} },
},

[450] = { en = "A Recipe For Death", tier = 1,
  t = "Een recept voor de dood",
  d = "Je kunt de Royal Apothecary Society nog meer van dienst zijn, $N.$b$bToen Arugal zijn ellendige magie over het bos uitsprak, vervloekte hij een van onze veelbelovendste leden: Apothecary Berard. Nu is Berard een hersenloze dienaar van Arugal, en hebben we niets aan hem. Maar zijn ontdekkingen kunnen wel waardevol zijn. Hij bestudeerde een oude plaag die heel lang geleden al het leven in het water van Lake Lordamere heeft gedood.$b$bHaal Berard's Journal uit zijn studeerkamer in de Pyrewood Village Inn en breng het naar Apothecary Renferrel.",
  o = "Haal het dagboek van Apothecary Berard uit Pyrewood Village en breng het naar Apothecary Renferrel in de Sepulcher.",
  p = "Ik zie dat je terug bent, $N.",
  c = "Het dagboek van Apothecary Berard! Jij bent echt dapper, $N. Laten we eens kijken wat Berard deed voordat hij gek werd...",
  g = { {"van dienst zijn", "to be of service"}, {"ellendige", "wretched (ellendig)"}, {"uitsprak", "cast, spoke (uitspreken)"}, {"vervloekte", "cursed (vervloeken)"}, {"veelbelovendste", "most promising (veelbelovend)"}, {"hersenloze", "mindless (hersenloos)"}, {"hebben we niets aan hem", "he is useless to us"}, {"ontdekkingen", "findings (ontdekking)"}, {"plaag", "plague"}, {"studeerkamer", "study (room)"}, {"dagboek", "journal, diary"}, {"dapper", "brave"} },
},

[438] = { en = "The Decrepit Ferry", tier = 1,
  t = "De Decrepit Ferry",
  d = "$N, we hebben een nieuw nest van de Scourge ontdekt: de Decrepit Ferry. De veerpont ligt ten oosten van de Sepulcher. Rot hides en andere ondoden patrouilleren daar veel.$B$BDe Scourge moet een reden hebben om dat gebied te bezetten. Ga naar de Decrepit Ferry en zoek uit waarom de Scourge daar is.",
  o = "Ga naar de Decrepit Ferry.$B$BZoek uit waarom de Scourge daar is.",
  c = "In deze boot ligt een stapel ingepakte lijken. En als je naar het oosten kijkt, over Lordamere Lake, zie je aan de overkant een steiger op Fenris Isle.$B$BWat er met de lijken gebeurt, moet op Fenris Isle te vinden zijn.",
  g = { {"nest", "hive, nest"}, {"veerpont", "ferry"}, {"ondoden", "undead (ondode)"}, {"patrouilleren", "to patrol"}, {"bezetten", "to occupy"}, {"zoek uit", "find out (uitzoeken)"}, {"stapel", "pile, heap"}, {"ingepakte", "wrapped (ingepakt)"}, {"lijken", "corpses (lijk)"}, {"overkant", "other side"}, {"steiger", "dock, jetty"} },
},

[439] = { en = "Rot Hide Clues", tier = 1,
  t = "Aanwijzingen over de rot hides",
  d = "Tussen de lijken steekt een hand naar buiten, zonder doek eromheen. Het is de hand van een vrouw. Hij zit vol putjes van de plaag, maar is nog vrij vers.$B$BAan de hand zit een ring. Je haalt de ring eraf en bekijkt hem. Er staat iets in gegraveerd:$B$B\"Voor Deliah\"",
  o = "Breng Deliah's Ring naar High Executor Hadrec in de Sepulcher.",
  p = "$N. Je bent terug, dus ik neem aan dat je onderzoek iets heeft opgeleverd?",
  c = "Zeg je dat deze ring werd gedragen door een vrouw die pas is gedood?$B$BDe enige plek in de buurt waar zo'n lichaam vandaan kan komen, zijn de massagraven in Tirisfal. De Rot Hide Gnolls brengen die lijken vast naar Fenris Isle!",
  g = { {"aanwijzingen", "clues (aanwijzing)"}, {"steekt naar buiten", "protrudes, sticks out (naar buiten steken)"}, {"doek", "cloth, wrapping"}, {"putjes", "pockmarks, little pits (putje)"}, {"vrij vers", "relatively fresh"}, {"gegraveerd", "engraved (graveren)"}, {"neem aan", "assume (aannemen)"}, {"opgeleverd", "produced, yielded (opleveren)"}, {"gedragen", "worn (dragen)"}, {"massagraven", "mass graves (massagraf)"} },
},

[440] = { en = "The Engraved Ring", tier = 1,
  t = "De gegraveerde ring",
  d = "Wil je de man of geliefde vinden die Deliah haar ring gaf? Praat dan met Magistrate Sevren in Brill. Hij heeft vast gegevens over mensen die pas zijn overleden. Met wat geluk kan hij ontdekken wie Deliah is.$B$BMaar ik zou er niet op hopen. Wie haar de ring ook gaf, hij is waarschijnlijk dood. En als hij ondood is, kan Deliah hem waarschijnlijk niets meer schelen.",
  o = "Breng Deliah's Ring naar Magistrate Sevren in Brill.",
  p = "Hallo, $N. Wat brengt je terug naar Brill?",
  c = "Er woonde inderdaad een Deliah in Brill, nog niet zo lang geleden. Ze werd begraven in het massagraf. Maar als het waar is wat je zegt, dan hebben de Rot Hide Gnolls haar lichaam gestolen en naar Silverpine gebracht.$b$bDe Rot Hides moeten vernietigd worden, net als de hele Scourge. Ik vertrouw erop dat je daar werk van maakt.",
  g = { {"gegraveerde", "engraved (gegraveerd)"}, {"geliefde", "beloved, loved one"}, {"gegevens", "records, data"}, {"overleden", "died (overlijden)"}, {"ondood", "undead"}, {"kan hem niets schelen", "he doesn't care (schelen)"}, {"begraven", "buried (begraven)"}, {"massagraf", "mass grave"}, {"gestolen", "stolen (stelen)"}, {"werk van maakt", "take steps, get on with it (werk maken van)"} },
},

[441] = { en = "Raleigh and the Undercity", tier = 1,
  t = "Raleigh en de Undercity",
  d = "Deliah had een man, Raleigh, die nu in de Undercity woont. Als de Deliah uit Brill de eigenaar van deze ring was, dan weet Raleigh dat.$B$BRaleigh is in de Trade Quarter van de Undercity.",
  o = "Breng Deliah's Ring naar Raleigh.",
  p = "Ken ik jou?",
  c = "Ja, deze ring was van mijn vrouw. Haar lot was het lot van iedereen die deze zware tijden niet overleeft. Ik voel niets bij haar dood. En ook niet bij jouw verhaal over de diefstal van haar lichaam.$b$bZulke gevoelens zijn al lang koud in mij. Maar er brandt nog wel een verlangen in mijn dode hart, $N.$b$bHet verlangen naar wraak.",
  g = { {"eigenaar", "owner"}, {"lot", "fate"}, {"overleeft", "survives, endures (overleven)"}, {"diefstal", "theft, abduction"}, {"gevoelens", "feelings (gevoel)"}, {"verlangen", "desire, longing"}, {"wraak", "revenge"} },
},

[446] = { en = "Thule Ravenclaw", tier = 1,
  t = "Thule Ravenclaw",
  d = "Deze ichor is gemaakt door een oude collega van me: Thule Ravenclaw. Hij was een jonge, veelbelovende magiër vóór de grote oorlog. Maar toen de Lich King aan de macht kwam, verraadde hij zijn broeders en sloot hij zich aan bij de Scourge.$B$BIk wist niet dat hij nog leeft. En ook niet dat hij de Rot Hides leidt in hun aanvallen op ons!$B$BIk ken veel van zijn spreuken, en ik kan helpen een drankje te maken dat ertegen werkt. Breng deze rol terug naar Apothecary Renferrel. Er staan de toverformules op die nodig zijn voor het drankje.",
  o = "Breng Bethor's Scroll naar Apothecary Renferrel in de Silverpine Sepulcher.",
  p = "Gegroet, $N. Wat had Bethor te zeggen?",
  c = "Er zit krachtige magie in deze rol. Ik heb zulke krachten nog nooit in een drankje gebruikt... Het wordt een krachtig mengsel. Het zal je goed helpen als je Thule aanvalt in zijn burcht op Fenris Isle.",
  g = { {"ichor", "ichor: a strange fluid, like blood"}, {"veelbelovende", "promising (veelbelovend)"}, {"magiër", "mage"}, {"verraadde", "betrayed (verraden)"}, {"broeders", "brethren (broeder)"}, {"sloot zich aan bij", "allied with, joined (zich aansluiten bij)"}, {"rol", "scroll"}, {"toverformules", "incantations (toverformule)"}, {"mengsel", "mixture"}, {"burcht", "stronghold, castle"} },
},

[448] = { en = "Report to Hadrec", tier = 1,
  t = "Meld je bij Hadrec",
  d = "Meld je bij High Executor Hadrec voordat je Fenris Isle aanvalt. Misschien heeft hij meer informatie of uitrusting die je nodig hebt.",
  o = "Meld je bij High Executor Hadrec in de Sepulcher.",
  c = "Als het waar is wat Bethor zegt, dan is Thule Ravenclaw een macht die we moeten aanpakken, en snel.$B$BOm je hierbij te helpen, mag je iets uit onze wapenvoorraad hier nemen...",
  g = { {"meld je", "report (zich melden)"}, {"aanvalt", "attack (aanvallen)"}, {"uitrusting", "equipment"}, {"macht", "force, power"}, {"aanpakken", "to deal with"}, {"wapenvoorraad", "arsenal"} },
},

[479] = { en = "Ambermill Investigations", tier = 1,
  t = "Onderzoek in Ambermill",
  d = "Dalar probeert te ontdekken waar de spreuken van de tovenaars vandaan komen. Voorlopig moeten we hen zoveel mogelijk vertragen...$b$bDe bezweerders, magiërs en beschermers dragen zeker de hangers bij zich. Pak ze af en breng ze mee.$b$bNeem de hoofdweg naar het zuiden en dan de oostelijke afslag naar Ambermill.",
  o = "Haal 8 Dalaran Pendants voor Shadow Priest Allister in de Sepulcher.",
  p = "We moeten opschieten. Hun plannen mogen niet slagen, anders verliezen we misschien onze greep op Silverpine Forest.",
  c = "Dalar heeft ontdekt dat het weven van de magie al ver gevorderd is, ondanks de tegenslag.$b$bEen heel machtige tovenaar leidt de magische energie. Hij moet snel worden tegengehouden.",
  g = { {"voorlopig", "for now"}, {"vertragen", "to slow down"}, {"bezweerders", "conjurers (bezweerder)"}, {"beschermers", "protectors (beschermer)"}, {"hangers", "pendants (hanger)"}, {"afslag", "fork, turn-off"}, {"opschieten", "to hurry"}, {"slagen", "to succeed"}, {"greep", "hold, grip"}, {"weven", "weaving"}, {"ver gevorderd", "far along"}, {"tegenslag", "setback"}, {"tegengehouden", "stopped (tegenhouden)"} },
},

[443] = { en = "Rot Hide Ichor", tier = 1,
  t = "Ichor van de rot hides",
  d = "Voordat we Fenris Isle aanvallen, moeten we weten wie er achter de rot hide gnolls zit. Onze apothekers denken dat hun oorsprong ligt in de vreemde vloeistof die door hun lichamen stroomt.$B$BGa naar Fenris Isle, ten oosten van de Decrepit Ferry, en verzamel rot hide ichor van de gnolls die je daar vindt. Breng het naar Apothecary Renferrel. Hij staat buiten de Sepulcher.",
  o = "Breng 8 flessen rot hide ichor naar Apothecary Renferrel in de Sepulcher.",
  p = "Heb je de rot hide ichor, $N?",
  c = "Heel goed. Deze ichor helpt ons om te begrijpen wat de rot hides zijn, en laat ons misschien hun zwakte zien...$B$B...als ze er een hebben.",
  g = { {"ichor", "ichor: a strange fluid, like blood"}, {"oorsprong", "origin"}, {"vloeistof", "fluid, liquid"}, {"stroomt", "flows (stromen)"}, {"flessen", "bottles (fles)"}, {"zwakte", "weakness"} },
},

[444] = { en = "Rot Hide Origins", tier = 1,
  t = "De oorsprong van de rot hides",
  d = "Ik heb de ichor die je bracht ingekookt en gescheiden in zijn basisdelen. Mijn resultaten zijn niet zeker. Maar ik heb wel vastgesteld dat er magie van heksenmeesters en necromanten is gebruikt om de ichor te maken.$B$BIk blijf de ichor bestuderen. Ondertussen wil ik dat je een monster naar Bethor Iceshard in de Undercity brengt. Bethor is geen apotheker, maar zijn kennis van magie kan helpen om het raadsel van de rot hides op te lossen.$B$BGa. Je vindt Bethor in de Magic Quarter van de Undercity.",
  o = "Breng de Sample Ichor naar Bethor Iceshard in de Undercity.",
  p = "Mijn onderzoek vraagt veel concentratie. Ik hoop dus dat je bezoek niet onbelangrijk is.",
  c = "In deze stof zitten krachtige spreuken. Sommige heb ik al heel, heel lang niet gezien...$B$BEen moment. Ik moet een spreuk van waarzeggerij uitspreken...",
  g = { {"oorsprong", "origin"}, {"ingekookt", "reduced, boiled down (inkoken)"}, {"gescheiden", "separated (scheiden)"}, {"basisdelen", "base components (basisdeel)"}, {"vastgesteld", "determined (vaststellen)"}, {"heksenmeesters", "warlocks (heksenmeester)"}, {"necromanten", "necromancers (necromant)"}, {"monster", "sample"}, {"raadsel", "mystery, riddle"}, {"onbelangrijk", "unimportant, frivolous"}, {"stof", "substance"}, {"waarzeggerij", "divination"}, {"uitspreken", "to cast, to speak (a spell)"} },
},

[857] = { en = "The Tear of the Moons", tier = 2,
  t = "De Tear of the Moons",
  d = "De macht was van mij! In mijn eigen handen! En ik wil hem terug! Terug, zeg ik!$b$bDie vuile gravers hebben hem opgegraven... zo mooi was hij. Hij kreeg de naam Tear of the Moons, en hij was de eerste grote vondst die we bij Bael Modan deden.$b$bHij had van mij moeten zijn! Van mij, zeg ik!$b$bGeneral Twinbraid werd jaloers op de macht die hij me gaf. Hij sloot hem op in de Keep. Hij noemde hem vervloekt! De dwaas!$b$bAnderen wilden hem hebben, en die moesten tegengehouden worden! Die schoft Twinbraid heeft me weggejaagd.$b$bNu wil ik hem terug. Terug, zeg ik!",
  o = "Feegly the Exiled wil dat je de Tear of the Moons voor hem terughaalt.",
  p = "Waar is de Tear of the Moons? Ik heb hem nu nodig! Nodig, zeg ik!",
  c = "Eindelijk is de macht weer van mij! Van mij, zeg ik!",
  g = { {"macht", "power"}, {"vuile", "dirty (vuil)"}, {"gravers", "diggers, excavators (graver)"}, {"opgegraven", "dug up, uncovered (opgraven)"}, {"vondst", "discovery, find"}, {"jaloers", "jealous"}, {"sloot", "locked (sluiten; opsluiten = lock away)"}, {"vervloekt", "cursed"}, {"dwaas", "fool"}, {"tegengehouden", "stopped (tegenhouden)"}, {"schoft", "bastard, scoundrel"}, {"weggejaagd", "driven off (wegjagen)"}, {"terughaalt", "gets back, retrieves (terughalen)"} },
},

[1145] = { en = "The Swarm Grows", tier = 2,
  t = "De zwerm groeit",
  d = "Veel reizigers die door de Crossroads zijn gekomen, hebben me geholpen om eieren te verzamelen in het Field of Giants. Velen van hen vertellen verhalen over hoe dodelijk de wezens zijn. Ik heb genoeg gehoord om die insecten een veel grotere dreiging te vinden dan mijn meesters eerst dachten.$B$BIk heb een koerier nodig die naar Orgrimmar reist om Belgrom Rockmaul te ontmoeten. Het is geen eenvoudige zaak, dus er moet iemand gaan die de taak serieus neemt.$B$BBelgrom is meestal te vinden buiten het gildehuis van de krijgers.",
  o = "Breng Korran's Sealed Note naar Belgrom Rockmaul in Orgrimmar.",
  p = "Ik benijd je, $c. Je ziet eruit als iemand die al een tijdje buiten de muren van Orgrimmar is geweest.$B$BIk zou zelf ook reizen in naam van de Warchief, als Thrall mijn vaardigheden hier in de stad niet nodig had. Maar hij leidt ons goed, en ik vertrouw op zijn oordeel. Ik blijf hier zo lang als hij me nodig heeft.",
  c = "Ah, een briefje van Korran. Hij is al een hele tijd een trouwe dienaar. Ik vroeg me al af hoe zijn taken in de Crossroads gingen.",
  g = { {"zwerm", "swarm"}, {"reizigers", "travelers (reiziger)"}, {"dodelijk", "deadly"}, {"dreiging", "threat"}, {"koerier", "courier"}, {"eenvoudige zaak", "simple matter"}, {"gildehuis", "guild house"}, {"benijd", "envy (benijden)"}, {"vaardigheden", "skills (vaardigheid)"}, {"oordeel", "judgement"}, {"trouwe", "loyal (trouw)"}, {"dienaar", "servant"}, {"vroeg me af", "wondered (zich afvragen)"} },
},

})

